_________
(1) برقم (٢٦٤٨).(2) تقدم تخريجهما في (٢٧).(3) كذا في "د" "م": "عروة" تحريف، صوابه: "عَزْرَة"، كما في مصدر الرواية وكتب الرجال.(4) كذا في "د" "م": "ابن نعيم" تحريف، صوابه: "ابن يَعْمر"، كما في مصدر الرواية وكتب الرجال، وهو يحيى بن يعمر البصري.

أُرِيدُ أَنْ أَشُقَّ عَلَيْكَ سَتَجِدُنِي إِنْ شَاءَ اللَّهُ مِنَ الصَّالِحِينَ} [القصص: 27]، وقال كليم الرحمن للخضر: {سَتَجِدُنِي إِنْ شَاءَ اللَّهُ صَابِرًا} [الكهف: 69]، وقال قوم موسى له: {وَإِنَّا إِنْ شَاءَ اللَّهُ لَمُهْتَدُونَ} [البقرة: 70]، وقال لسيد ولد آدم وأكرمهم عليه صلوات الله وسلامه عليه: {وَلَا تَقُولَنَّ لِشَيْءٍ إِنِّي فَاعِلٌ ذَلِكَ غَدًا (23) إِلَّا أَنْ يَشَاءَ اللَّهُ} [الكهف: 23 - 24]، وقال: {قُلْ لَا أَمْلِكُ لِنَفْسِي ضَرًّا وَلَا نَفْعًا إِلَّا مَا شَاءَ اللَّهُ} [يونس: 49]، وقال: {سَنُقْرِئُكَ فَلَا تَنْسَى (6) إِلَّا مَا شَاءَ اللَّهُ} [الأعلى: 6 - 7]، وقال عن أهل الجنة: {خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ} [هود: 108] وعن أهل النار كذلك؛ ليبين أن الأمر راجع إلى مشيئته، ولو شاء لكان غير ذلك. وقال: {رَبُّكُمْ أَعْلَمُ بِكُمْ إِنْ يَشَأْ يَرْحَمْكُمْ أَوْ إِنْ يَشَأْ يُعَذِّبْكُمْ} [الإسراء: 54]، وقال: {يَغْفِرُ لِمَن يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ} [آل عمران: 129]، وقال: {إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَنْ يَشَاءُ وَيَقْدِرُ} [الإسراء: 30]، وقال: {وَلَوْ بَسَطَ اللَّهُ الرِّزْقَ لِعِبَادِهِ لَبَغَوْا فِي الْأَرْضِ وَلَكِنْ يُنزِلُ بِقَدَرٍ مَا يَشَاءُ} [الشورى: 27]، وقال: {يَمْحُو اللَّهُ مَا يَشَاءُ وَيُثْبِتُ} [الرعد: 39]، وقال: {مَنْ يَشَإِ اللَّهُ يُضْلِلْهُ وَمَنْ يَشَأْ يَجْعَلْهُ عَلَى صِرَاطٍ مُسْتَقِيمٍ} [الأنعام: 39]، وقال: {وَمَا أَرْسَلْنَا مِنْ رَسُولٍ إِلَّا بِلِسَانِ قَوْمِهِ [لِيُبَيِّنَ لَهُمْ] (1) فَيُضِلُّ اللَّهُ مَنْ يَشَاءُ وَيَهْدِي مَنْ يَشَاءُ وَهْوَ الْعَزِيزُ الْحَكِيمُ} [إبراهيم: 4]، وقال: {وَيُضِلُّ اللَّهُ الظَّالِمِينَ وَيَفْعَلُ اللَّهُ مَا يَشَاءُ} [إبراهيم: 27]، وقال: {وَلَكِنْ جَعَلْنَاهُ نُورًا نَهْدِي بِهِ مَنْ نَشَاءُ مِنْ عِبَادِنَا}
_________
(1) قوله تعالى: ﴿لِيُبَيِّنَ لَهُمْ﴾ ساقط من "د" "م"، وألحقها في حاشية "ج" مصحِّحًا ..

[الشورى: 52]، وقال: {قُلْ لِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ يَهْدِي مَنْ يَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ} [البقرة: 142]، وقال: {أَنْ تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَأْتِكُمْ مَثَلُ الَّذِينَ خَلَوْا مِنْ قَبْلِكُمْ مَسَّتْهُمُ الْبَأْسَاءُ وَالضَّرَّاءُ وَزُلْزِلُوا إِلَى يَقُولَ الرَّسُولُ} [البقرة: 213]، وقال: {(15) قُلْ لَوْ شَاءَ اللَّهُ مَا تَلَوْتُهُ عَلَيْكُمْ وَلَا أَدْرَاكُمْ بِهِ} [يونس: 16]، وقال: {نَحْنُ خَلَقْنَاهُمْ وَشَدَدْنَا أَسْرَهُمْ وَإِذَا شِئْنَا بَدَّلْنَا أَمْثَالَهُمْ تَبْدِيلًا} [الإنسان: 28]، وقال: {وَمَا يَذْكُرُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ} [المدثر: 56]، وفي الآية الأخرى: {وَمَا يَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ} [الإنسان: 30]، فأخبر أن مشيئتهم وفعلهم موقوفان (1) على مشيئته لهم هذا وهذا. وقال تعالى: {قُلِ اللَّهُمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَنْ تَشَاءُ وَتَنْزِعُ الْمُلْكَ مِمَّنْ تَشَاءُ وَتُعِزُّ مَنْ تَشَاءُ وَتُذِلُّ مَنْ تَشَاءُ بِيَدِكَ الْخَيْرُ إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ} [آل عمران: 26]، وقال: {(24) وَاللَّهُ يَدْعُو إِلَى دَارِ السَّلَامِ وَيَهْدِي مَنْ إِلَى إِلَى صِرَاطٍ} [يونس: 25]، وقال: {وَيُعَذِّبَ الْمُنَافِقِينَ إِنْ شَا أَوْ يَتُوبَ عَلَيْهِمْ} [الأحزاب: 24]. وقوله: {يَخْتَصُّ بِرَحْمَتِهِ مَنْ يَشَاءُ} [آل عمران: 74]، وقوله: {وَلَكِنَّ اللَّهَ يُزَكِّي مَنْ يَشَاءُ} [النور: 21]، وقوله: {وَاللَّهُ يُضَاعِفُ لِمَنْ يَشَاءُ} [البقرة: 261]، وقوله: {نُصِيبُ بِرَحْمَتِنَا مَنْ نَشَاءُ} [يوسف: 56]، وقوله: {نَرْفَعُ دَرَجَاتِ مَنْ نَشَاءُ} [الأنعام: 83]، وقوله: {ذَلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَنْ يَشَاءُ} [الجمعة: 4]، وقوله: {وَلَكِنَّ اللَّهَ يَمُنُّ عَلَى مَنْ يَشَاءُ مِنْ عِبَادِهِ} [إبراهيم: 11]، وقوله: {فَنُجِي مَنْ نَشَاءُ} [يوسف: 110]، وقوله: {فَيَبْسُطُهُ فِي السَّمَاءِ كَيْفَ يَشَاءُ}
_________
(1) "موقوفان" ساقطة من "د"، واستدرك موضعها الناسخ بلحق لم أتمكن من قراءته.

قال أبو عبيدة: "الأزيز الالتهاب والحركة، كالتهاب النار في الحطب، يقال: أُزَّ قدْرَكَ، أي: ألْهِب تحتها النار، وائْتَزَّت القدر إذا اشتد غليانها" (1) ، وهذا اختيار الأخفش (2) . والتحقيق أن اللفظة تجمع المعنيين جميعًا. قالت القدرية: معنى {أَرْسَلْنَا الشَّيَاطِينَ عَلَى الْكَافِرِينَ} خلّينا بينهم وبين الكافرين، وليس معناه التسليط. قال أبو علي: "الإرسال يستعمل بمعنى التخلية بين المرسل وما يريد، فمعنى الآية: خلينا بين الشياطين وبين الكافرين، ولم نمنعهم منهم، ولم نعذهم، بخلاف المؤمنين الذين قيل فيهم: {إِنَّ عِبَادِي لَيْسَ لَكَ عَلَيْهِمْ سُلْطَانٌ} " (3) . قال الواحدي: "وإلى هذا الوجه تذهب القدرية في معنى الآية"، قال: "وليس المعنى على ما ذهبوا إليه" (4) . وقال أبو إسحاق: "والمختار أنهم أُرسلوا عليهم، وقُيِّضوا لهم بكفرهم، كما قال تعالى: {وَمَنْ يَعْشُ عَنْ ذِكْرِ الرَّحْمَنِ نُقَيِّضْ لَهُ شَيْطَانًا فَهْوَ لَهُ قَرِينٌ} [الزخرف: 36]، وقال: {لَهُمْ قُرَنَاءَ فَزَيَّنُوا لَهُمْ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ}
_________
(1) حكاه في "تهذيب اللغة" (أزز) (١٣/ ٢٨١)، وفي "مجاز القرآن" (٢/ ١١) تفسير آخر.(2) حكاه في "البسيط" (١٤/ ٣٢٤)، وليس هو في نشرة "معاني القرآن" للأخفش.(3) حكاه في "البسيط" (١٤/ ٣٢١).(4) "البسيط" (١٤/ ٣٢٢).

وهذه نسخة الضلال وعَلَمُ الشقاء، كما أن نسخة الهدى وعَلَم السعادة فهمٌ صحيح وقصد صالح، والله المستعان. وتأمل قوله سبحانه: {ثُمَّ انْصَرَفُوا صَرَفَ اللَّهُ قُلُوبَهُمْ}، كيف جعل هذه الجملة الثانية ـ سواء كانت خبرًا أو دعاء ـ عقوبة لانصرافهم، فعاقبهم عليه بصرْفٍ آخر غير الصرْف الأول، فإن انصرافهم كان لعدم إرادته سبحانه ومشيئته لإقبالهم؛ لأنه لا صلاحية فيهم ولا قبول، فلم يشأ لهم الإقبال والإذعان، فانصرفت قلوبهم بما فيها من الجهل والظلم عن القرآن، فجازاهم على ذلك صرفًا آخر غير الصرف الأول، كما جازاهم على زيغ قلوبهم عن الهدى إزاغة أخرى غير الزيغ الأول، كما قال تعالى: {فَلَمَّا زَاغُوا أَزَاغَ اللَّهُ قُلُوبَهُمْ} [الصف: 5]، وهكذا إذا أعرض العبد عن ربه جازاه سبحانه بأن يعرض بقلبه عنه، فلا يمكّنه من الإقبال عليه. ولتكن قصة إبليس منك على ذكر، تنتفع بها أتمَّ انتفاع، فإنه لما عصى ربّه تعالى ولم ينقد لأمره، وأصرَّ على ذلك؛ عاقبه بأن جعله داعيًا إلى كل معصية، فعاقبه على معصيته الأولى بأصول المعاصي وفروعها، صغيرها وكبيرها، وصار هذا الإعراض والكفر منه عقوبة لذلك الإعراض والكفر السابق، فمن عقاب السيئة السيئة بعدها، كما أن من ثواب الحسنة الحسنة بعدها. فإن قيل: ف كيف يلتئم إنكاره سبحانه عليهم الانصراف والإعراض وهو منه ، وقد قال تعالى: {فَأَنَّى تُصْرَفُونَ} [يونس: 32]، و {فَأَنَّى (1) تُؤْفَكُونَ}
_________
(1) في الأصول الخطية: "أنى".

وقوله: «فأبواه يُهَوِّدانه» بَيّن فيه أنهم يغيّرون الفطرة التي فُطِر عليها. وأيضًا: فإنه شبّه ذلك بالبهيمة التي تولَد مُجْتَمعة الخَلْق لا نقص فيها، ثم تُجْدَع بعد ذلك، فعُلِم أنّ التغيير وارد على الفطرة السليمة التي وُلِد العبد عليها. وأيضًا: فإن الحديث مطابق للقرآن، كقوله: {فِطْرَتَ اللَّهِ الَّتِي فَطَرَ النَّاسَ عَلَيْهَا} [الروم: 30]، وهذا يعم جميع الناس، فعُلِم أنّ الله سبحانه فطر الناس كلهم على فطرته المذكورة. وأيضًا: فإنه أضاف الفطرة إليه إضافة مدح لا إضافة ذم، فعُلِم أنها فطرة محمودة لا مذمومة، كدين الله وبيته وناقته. وأيضًا: فإنه قال: {فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا فِطْرَتَ اللَّهِ الَّتِي فَطَرَ النَّاسَ عَلَيْهَا} [الروم: 30]، وهذا نَصْبٌ على المصدر الذي دلّ عليه الفعل الأول عند سيبويه وأصحابه، فدلَّ على أن إقامة الوجه لله (1) حنيفًا هو فطرة الله التي فطر الناس عليها. وأيضًا: فإن هذا تفسير السلف كما تقدم. قال ابن جرير (2) : يقول: فسدِّد وجهك نحو الوجه الذي وجّهك الله يا محمد لطاعته ــ وهي الدين ــ، {حَنِيفًا} يقول: مستقيمًا لدينه وطاعته، {فِطْرَتَ اللَّهِ} يقول: صنعة الله التي خَلَق الناس عليها، ونَصْبُ {فِطْرَتَ}
_________
(1) كذا في «د»: «لله» كأنه سبق قلم، وفي «درء التعارض»: «للدين»، وهو الأشبه.(2) «جامع البيان» (١/ ٣١٣).

وفي تفسير الآية نزاع بين الأئمة (1) ، وكذلك في خلق الأرواح قبل الأجساد قولان معروفان. لكن المقصود هنا أن هذا إن كان حقًّا فهو توكيد لكونهم ولدوا على تلك المعرفة والإقرار، فهذا لا يخالف ما دلت عليه الأحاديث من أنه يولد على الملة، وأن الله خلق خلقه حنفاء، بل هو مؤيد لذلك (2) . وأما قول القائل: إنهم في ذلك الإقرار انقسموا إلى مطيع وكافر، فهذا لم يُنقل عن أحد من السلف فيما أعلم إلا عن السُّدِّي في تفسيره، قال: لما أخرج الله آدم من الجنة ــ قبل أن يهبطه من السماء ــ مسح صفحة ظهره اليمنى، فأخرج منه ذرّية بيضاء مثل اللؤلؤ كهيئة الذرّ، فقال لهم: ادخلوا الجنة برحمتي. ومسح صفحة ظهره اليسرى، فأخرج منه ذرّية سوداء كهيئة الذرّ، فقال: ادخلوا النار ولا أبالي. ذلك قوله: {وَأَصْحَابُ الْيَمِينِ} [الواقعة: 27]، {وَأَصْحَابُ الشِّمَالِ} [الواقعة: 41] ثم أخذ منهم الميثاق، فقال: {أَلَسْتُ بِرَبِّكُمْ قَالُوا بَلَى} فأعطاه طائفةٌ طائعين، وطائفةٌ كارهين على وجه التَّقِيّة، فقال هو والملائكة: {شَهِدْنَا يَقُولُوا تَقُولُوا يَوْمَ الْقِيَامَةِ إِنَّا كُنَّا عَنْ هَذَا} [الأعراف: 172]، فليس أحد من ولد آدم إلا وهو يعرف الله بأنه ربّه، وذلك قوله عز وجل: {وَلَهُ أَسْلَمَ مَنْ فِي السَّمَاوَاتِ وَالْأَرْضِ طَوْعًا وَكَرْهًا} [آل عمران: 83]، وكذلك (3) قوله: {قُلْ فَلِلَّهِ الْحُجَّةُ الْبَالِغَةُ فَلَوْ شَاءَ لَهَدَاكُمْ أَجْمَعِينَ}
_________
(1) تحتمل في «د»: «الأمة»، والمثبت أليق بالسياق.(2) كذا في «د» و «درء التعارض»: «مؤيد لذلك»، وفي نسخة خطية منه: «مريد لذلك».(3) كذا في «د»: «وكذلك»، وفي مصدر النقل: «وذلك»، وهو الأقرب.
